# Simple backtracking search
def solve():
    assignment = [0] * 19  # assignment[i] = subset for integer i (1-indexed)
    sums = [0, 0, 0]
    target = 57

    def backtrack(i):
        if i == 19:
            return all(s == target for s in sums)
        for subset in range(3):
            if sums[subset] + i <= target:
                sums[subset] += i
                assignment[i] = subset
                if backtrack(i + 1):
                    return True
                sums[subset] -= i
                assignment[i] = 0
        return False

    if backtrack(1):
        return assignment[1:]
    return None

result = solve()
print(result)
if result:
    # Verify
    subsets = [[], [], []]
    for i, s in enumerate(result):
        subsets[s].append(i + 1)
    for s in subsets:
        print(f"Subset: {s}, sum = {sum(s)}")
